import{j as e}from"./index-C8GeSimu.js";import{L as t,l as a}from"./LocationPage-s-s1D5_W.js";import"./Breadcrumbs-BX4_sVd4.js";import"./building-2-CwVvfN-g.js";import"./info-C0E7D3Af.js";import"./circle-help-DRPraxRJ.js";const n={path:"/locations/turkey",h1:"Software and AI Development for Businesses in Turkey",valueProp:"An India-based software and AI development partner serving businesses in Turkey — marketplaces, booking and service products, AI assistants and voice agents, with every local integration and the Turkish interface scoped as work of its own.",heroHighlights:["Developed in Indore, India, for companies serving customers in Turkey","Consumer-facing products built for the traffic of a campaign weekend, not just a demo","Payment, messaging and invoicing integrations scoped and quoted one provider at a time","Turkish interface text commissioned as professional localization, never machine-translated"],intro:["Most of what reaches us from Turkey has users outside the company. A marketplace that has to be fair to buyers and sellers at once; a booking or appointment product where a lost slot is a lost customer; a service application whose support load is the real cost of running it. Those products are judged in public, which changes what matters in the build: the flow a first-time user takes, what happens when the queue is long, and how quickly your own team can see what is going wrong.","They also arrive with a list. A payment provider, an SMS or messaging gateway, an accounting or e-invoicing system, a courier, sometimes a national identity or address service. Each of those is a piece of scoped work with its own interface, its own test credentials and its own failure behaviour, and we quote them individually rather than folding them into a line called integrations. You hold the commercial relationship with each provider; we build against what that provider publishes.","The AI work here is mostly conversational and clerical: assistants that answer from your own policies and catalogue, voice agents that handle a spoken enquiry inside your own product, structured consultation and requirement-collection systems that ask every caller the same questions and produce a written summary, and automation of the document and approval steps behind them. In each case a person stays on the decisions that touch a customer, an order or a payment.","On the practical side: Turkey has kept a single time zone at three hours ahead of UTC throughout the year since 2016, with no seasonal change, which puts Indian Standard Time a constant two and a half hours ahead of Turkish local time. Our working day therefore covers your morning and your early afternoon. Scope, milestone reviews and correspondence are in English; the Turkish interface and content are separately scoped professional localization, set out further down."],disclosure:{title:"A development team in India, serving a Turkish market",body:"SCS Softwares operates from Indore, Madhya Pradesh, India, and work for Turkish businesses is developed and delivered remotely from that office. What this page describes is where a service is available. It is not a claim of presence in Turkey, and no local office lies behind it.",points:["We hold no Turkish office, no branch, no Turkish company registration and no Turkish telephone number, and we never present ourselves as having one.","Every part of the engagement is remote: requirement collection, design review, milestone demonstrations, testing, release and handover happen online.","Nobody working on your project is employed outside India. We claim no employees, no representatives and no on-site attendance in Turkey.","We hold no relationship, agreement or agency with any Turkish bank, payment institution or messaging provider. Those contracts are yours; we integrate against the interface the provider documents.","We hold no approval, permit or registration from any Turkish authority, and no certification or audit report of any kind.","We do not describe our software as compliant with the KVKK or with any other framework, and we give no legal, tax, accounting or payment advice for Turkey.","This page and the project documentation are in English. Turkish-language interface text and content are available only as separately scoped professional localization."]},concerns:{eyebrow:"The first conversations",heading:"What Turkish buyers check before committing",intro:"A public-facing product fails publicly, so most of these questions are about what happens on a bad day rather than a good one. Answers, before you ask.",items:[{title:"Can you integrate our payment provider?",body:"Almost always, and it is scoped as its own item. We build against the provider documentation, using their test environment first, and we design what the product does when a payment is pending, fails or is refunded. The merchant agreement stays entirely yours."},{title:"Will it hold up on a campaign day?",body:"That is a question about what we test, not about a promise. We agree a target load in writing, test against it before release, and show you the numbers. Where the answer is that a component needs more headroom, you hear it before launch rather than during a campaign."},{title:"Who writes the Turkish text in the interface?",body:"A qualified translator or your own team, as a separate item in the scope. We build the interface so Turkish fits it correctly, and we place text that somebody accountable has approved. We do not draft the Turkish and we do not machine-translate it into production."},{title:"How is the price handled if we sell in more than one currency?",body:"Deliberately and early. Which currency amounts are stored in, how rounding works, where conversion happens and what appears on an invoice are all decided during discovery, because retrofitting a second currency touches the whole data model."},{title:"Where will customer data be stored?",body:"Wherever you decide, recorded before anything is provisioned. Hosting region, backups, retention, logging and every external service in the chain are settled with you while the design is still a document."},{title:"Can we change scope once the build has started?",body:"Yes, through a short and unexciting process: the change is written down, re-estimated, and either approved or deferred at the next milestone review. What we avoid is absorbing changes silently and then explaining a delay at the end."},{title:"How much can a voice agent actually be trusted with?",body:"A bounded amount, set in the specification. It can identify why someone is calling, answer from approved material, collect details and book or cancel within agreed limits. Refunds, disputes, price changes and anything sensitive go to a person."}]},services:{eyebrow:"What we build here",heading:"The services Turkish projects most often need",intro:"Each page describes the service in general terms. The note beside it is what changes when the product faces Turkish customers and the team building it sits in India.",items:[{path:"/services/mobile-app-development",label:"Mobile App Development",blurb:"Where most of these products are actually used: a customer application built for a first-time user on a mid-range phone and an ordinary mobile connection."},{path:"/services/web-application-development",label:"Web Application Development",blurb:"The public platform and the operations console behind it — listings, bookings, cases and the internal screens your team uses to keep them all moving."},{path:"/services/custom-software-development",label:"Custom Software Development",blurb:"Marketplace and settlement logic in particular: commission rules, payout timing, disputes and the ledger that has to reconcile at the end of every month."},{path:"/services/saas-development",label:"SaaS Development",blurb:"Subscription products for business customers: tenancy, plans, seats, trials, invoicing and the usage figures a renewal conversation depends on."},{path:"/services/ai-voice-agent-development",label:"AI Voice Agent Development",blurb:"Spoken assistance inside your own application or web product, with a defined set of permitted actions and a written rule for handing the caller to your team."},{path:"/services/ai-video-consultation-agents",label:"AI Video Consultation Agents",blurb:"Structured consultation and requirement collection: every enquiry asked the same questions, with a written summary a person reviews before anything is committed."},{path:"/services/ai-development",label:"AI Development",blurb:"Assistants grounded in your catalogue, policies and help material, answering with the source shown and escalating anything the material does not cover."},{path:"/services/ai-automation-integration",label:"AI Automation & Integration",blurb:"The provider integrations and the document and approval steps behind them — payments, messaging, invoicing and delivery, each with a record of what happened."},{path:"/services/software-modernization",label:"Software Modernization",blurb:"For a product that grew feature by feature and now breaks under its own weight: assessed, then rebuilt in releases that keep the existing users running."}]},projectTypes:{eyebrow:"Common briefs",heading:"Turkish projects that fit this way of working",intro:"These are the shapes of work we see most, and the ones where a remote team with written scope and milestone reviews does a genuinely good job.",items:[{title:"A marketplace with two sides to keep balanced",body:"Buyers, sellers, commission, payouts and disputes. The interesting engineering is in the settlement and the ledger, not in the listings — and that is where the scope has to be precise."},{title:"A booking or appointment product where slots are money",body:"Availability, capacity, cancellation rules, reminders and no-shows. Getting the concurrency right matters more than any screen: two people must never be able to hold the same slot."},{title:"A customer-service platform that replaces a shared inbox",body:"Requests arriving by phone, message and email into one queue, with routing, history, response templates and a view of what is actually taking the team all day."},{title:"Operational dashboards for a business that runs on daily numbers",body:"Orders, cancellations, payouts, stock and campaign performance in one screen, defined once so that two departments stop reporting different figures for the same day."},{title:"A voice or chat agent taking the repetitive half of enquiries",body:"Order status, availability, opening hours, basic changes. It handles what it is allowed to handle, and everything else reaches a person with the conversation already summarised."},{title:"Document and approval work still done by hand",body:"Invoices, contracts, applications or claims moving as attachments and spreadsheets. Automation reads the fields, routes the item and records each approval in a form somebody can audit later."}]},collaboration:{eyebrow:"How the work runs",heading:"From requirement collection to a launched product",intro:"Five stages, with a written scope at the front and a milestone review at the end of each build cycle. Nothing exotic — the point is that nothing is left implicit.",steps:[{title:"First call and an honest read on the idea",body:"A conversation about the product, the users and the market it launches into, ending with our real opinion — including the parts we think should be cut from a first version.",points:["Held while both working days overlap, which is your morning","An early view of effort, sequence and the two or three things that carry the risk","Any part of the brief we would not take on named in that call"]},{title:"Requirement collection and a written scope",body:"Structured sessions covering the user journeys, the rules behind them and every external service the product must speak to, written up as a scope with milestones and exclusions.",points:["Each provider integration listed separately with its own effort and test plan","Currency, invoicing, hosting and data requirements confirmed before development starts","An estimate given as a range, with the assumptions it rests on written beside it"]},{title:"Design, agreement and accounts",body:"Screen flows and the data model are reviewed with you before development, and the commercial and account setup is finished so no cycle stalls waiting for access.",points:["User journeys and data model approved in writing before implementation","Test credentials for every payment, messaging and third-party service obtained first","Agreement, billing currency, invoicing cycle and the people who sign off agreed first"]},{title:"Build cycles and milestone reviews",body:"Development in cycles, each closing with a demonstration on a real environment and a written review of what was accepted, what was rejected and what moved.",points:["A test environment open to your team throughout, not only on review days","Load and failure testing against an agreed target before any public release","Change requests re-estimated and approved in writing before they enter a cycle"]},{title:"Launch, monitoring and what follows",body:"Release is planned as its own exercise, with monitoring in place before the first real user arrives and a documented way back if something goes wrong.",points:["A launch plan covering data migration, provider switchover and rollback","Monitoring, alerting and error reporting handed over with the credentials and source","Continued development or support agreed separately, with no lock-in either way"]}]},communication:{eyebrow:"Time and contact",heading:"Two and a half hours, with India ahead of the Turkish clock",intro:"This is a small and completely stable difference, which makes scheduling easy. It is still worth writing down exactly what it gives you and what it does not.",points:["Turkey has stayed on a single time zone three hours ahead of UTC all year round since 2016, so there is no seasonal shift on your side to plan around.","Indian Standard Time is a constant two and a half hours ahead of Turkish local time, which means our working day is already well underway when yours begins.","The overlap therefore covers your morning and your early afternoon, and we agree a recurring meeting window inside it for demonstrations and milestone reviews.","The Turkish late afternoon and evening fall outside our working day. Messages sent then are picked up the following morning, and we plan around that rather than pretending otherwise.","Written notes follow every review, so a decision does not depend on which people were available for the call.","An escalation contact and an agreed response path are named at kick-off for anything that genuinely cannot wait for the next session."],note:"For a live consumer product, attention outside our working hours is a support arrangement with its own scope, response expectations and price — including what counts as an incident. We would rather agree that in writing than let a convenient time difference imply cover nobody has staffed."},security:{eyebrow:"Data, hosting and money",heading:"Hosting, currency and data questions closed before development",intro:"A product handling payments and personal data raises these questions on day one, so they are settled during discovery rather than after the architecture exists.",points:["The hosting region and the backup region are chosen with you and recorded in the agreement before anything is provisioned.","Card and payment credentials stay with the payment provider. The product holds a reference, and we design it so sensitive payment data never lands in your database or ours.","Every external service the product calls is listed during discovery, with what it receives, where it runs and who operates it.","Access is granted per person and per environment, reviewed during the project, and removed when someone leaves it.","Live customer records stay in the production environment. Testing runs on generated data and on the sandbox credentials each provider issues.","Confidentiality terms, ownership of everything we build and any data-processing agreement your advisers require are signed before the first cycle begins."],note:"We hold no certification and no audit report, and we do not present our software as satisfying the KVKK or any other data-protection framework. Those obligations sit with you as the organisation collecting the data, and the assessment is one only your own advisers can make. What we do is implement the controls they set out and document the implementation clearly enough to be examined."},oversight:{title:"What a person still has to approve",body:"A conversational agent talking to your customers is the highest-exposure AI in this list, because a wrong answer is delivered directly to the person it misleads. So the permitted actions are enumerated in the specification, and everything outside that list reaches a human.",points:["A voice or chat agent may act only inside the list of actions written into the specification; anything else is handed to a person with the conversation summarised.","Refunds, disputes, price changes, cancellations beyond an agreed limit and anything touching a payment always require human approval.","Assistants answer from your own approved material with the source shown, and say plainly when the material does not cover the question.","Extracted or generated values in a document workflow are proposals until a named person accepts them, and the acceptance is recorded.","Every automated action writes an audit entry — input, output, configuration, time and the approver — so a customer complaint can be reconstructed rather than guessed at.","The agent tells the customer it is not a human when asked, and the handover route to a person is available at any point in the conversation."]},localization:{title:"Language: English project, Turkish interface as scoped work",body:"The project runs in English — this page, the scope, the milestone reviews and the documentation. The product your customers use is a different question, and for a consumer product in Turkey the interface has to be properly Turkish. We treat that as real professional work rather than something a developer does with a translation tool, and we do not present ourselves as a Turkish-speaking team, because that would not be true.",points:["Engineering an interface that carries Turkish correctly is specific work: Turkish has both a dotted and a dotless i, and case conversion in most programming languages gets them wrong unless the locale is set explicitly — which quietly breaks logins, search, sorting and duplicate checks.","Text expansion, suffix-heavy grammar that resists English-style sentence assembly, name and address formats, and number and date formatting all have to be handled in the interface rather than patched afterwards.","The Turkish wording itself is a separate line in the scope, written by a professional translator or by your own team, and reviewed by somebody accountable for how it reads to a customer.","Automatic translation is a working aid inside our team at most. No machine-translated string reaches a customer-facing screen, a message, an invoice or a notification without a qualified human review.","Terms of service, privacy text, invoices and any regulated wording come from you or your advisers, and we place them exactly as supplied — we neither translate nor draft them.","Customer support conversations in Turkish are your side of the arrangement, not ours. Where a voice or chat agent is expected to speak Turkish, the scripts and approved answers are supplied and reviewed by someone who does."],note:"If the product needs Turkish-language support, Turkish sales material or Turkish contracts, put it on the table in the first call. These are genuine costs with genuine owners, and they belong in the scope rather than in an assumption that English will carry the whole thing."},engagement:{eyebrow:"Commercial options",heading:"How Turkish engagements are usually structured",intro:"Three arrangements cover most of this work. Consumer products typically begin with the first and continue in the second once real users arrive.",options:[{name:"First version, fixed scope",body:"A written scope for a launchable first version, delivered in milestones with a review at each one, and integrations itemised individually in the estimate.",bestFor:"Suits a product that needs to reach real users before anything else is decided."},{name:"Ongoing product team",body:"An agreed team working a prioritised backlog month by month, which is how most consumer products continue once launch has taught you what users actually do.",bestFor:"Suits a live product where the roadmap changes with the numbers."},{name:"Single integration or agent build",body:"One bounded piece of work — a payment or messaging integration, or one voice agent — with its own scope, its own test plan and a defined end.",bestFor:"Suits adding one capability to a product that already exists."}]},faqs:[{question:"Do you have an office, a branch or a registered company in Turkey?",answer:"No. SCS Softwares operates from Indore, India, and Turkish projects are delivered remotely from there. We hold no Turkish company registration, no branch, no address and no Turkish telephone number, and nothing here should be read as a presence in the country."},{question:"Does your team speak Turkish?",answer:"We make no such claim, because we could not stand behind it. The project runs in English. Turkish interface text, notifications, help content and any Turkish script for a voice or chat agent are separately scoped professional localization, written or reviewed by someone qualified to be accountable for it."},{question:"How do the two working days actually line up?",answer:"Turkey has been on a single year-round zone three hours ahead of UTC since 2016, and Indian Standard Time is a constant two and a half hours ahead of that. Our day starts before yours and ends in your early afternoon, so we agree a recurring meeting window inside your morning. The Turkish evening is outside our working day, and we do not offer cover there unless it is scoped as support."},{question:"Do you have a relationship with Turkish banks or payment providers?",answer:"None. We are not an agent, reseller or partner of any bank, payment institution or messaging provider in Turkey, and we give no payment or financial advice. You hold the merchant or service agreement directly; we build against the interface that provider publishes, test in their sandbox first, and design what your product does when a payment or a message fails."},{question:"Can you confirm the platform will satisfy the KVKK?",answer:"No, and we would be overstating a supplier position if we did. Those obligations rest with you as the organisation collecting personal data, and the assessment is one your own advisers make. What we can do is host in a region you choose, list every external processor before we build, implement the controls your advisers specify, and document the implementation so their assessment has something concrete to examine."},{question:"Do you hold any Turkish government approval, permit or certification?",answer:"We hold none of those, and no audit report or seal either. If a tender or a sector requires an approved, registered or certified supplier, it is worth checking that in the first conversation — it may rule us out, and knowing that early is cheaper for both sides than finding out at contract stage."},{question:"How do you test that the product survives a campaign or a launch day?",answer:"We agree a target — concurrent users, orders per minute, whatever the right measure is for the product — write it into the scope, and test against it before release rather than after. You get the results, including the parts that did not reach the target and what it would cost to fix them. We do not describe an untested figure as capacity."},{question:"Can you show us Turkish clients or local references?",answer:"We claim no Turkish clients and no local partnerships, and we will not fabricate one to win a project. What we can offer instead is a short paid requirement-collection exercise on your own product, whose output — the written scope, the integration list and the effort view — is yours whether or not you go further with us."}],otherMarkets:[{path:"/locations/united-states",label:"United States",blurb:"A working day that barely meets ours, run on written scope, recorded approvals and a change process both sides can point at."},{path:"/locations/united-kingdom",label:"United Kingdom",blurb:"Organisations that buy software through a formal process: documented requirements, supplier checks and approval in stages."},{path:"/locations/united-arab-emirates",label:"United Arab Emirates",blurb:"A similar appetite for consumer apps in a single market, with Arabic right-to-left interface engineering priced on its own."},{path:"/locations/canada",label:"Canada",blurb:"Internal business platforms across a country with six clock offsets, where reachable hours are agreed client by client."},{path:"/locations/australia",label:"Australia",blurb:"Almost no shared working hours, so open test environments and written handovers carry what a meeting normally would."},{path:"/locations/singapore",label:"Singapore",blurb:"The same clock distance in the opposite direction, applied to head-office platforms spanning several entities and currencies."},{path:"/locations/germany",label:"Germany",blurb:"A full specification and acceptance criteria agreed before implementation, with documentation and release evidence as deliverables."},{path:"/locations/netherlands",label:"Netherlands",blurb:"Integration-led platforms joining systems already in daily use, decided in short written notes and proved every cycle."}],cta:{title:"Tell us what your customers will be doing with it",body:"Answer a few questions for an indicative estimate, talk the product through with our AI consultation agent, or send the brief to the team in Indore and we will come back with what we think it really takes."}},l=()=>e.jsx(t,{content:a(n)});export{l as default};
